D.CompanionSkillText = {[101]={enter="10초간 플레이어의 방어력을 15% 증가시키고, 최대 HP의 15%만큼 피해를 흡수하는 보호막을 부여합니다.",actives={{unlock=1,desc="전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="주변 적들의 공격력을 10% 감소시킵니다."}}},[102]={enter="10초간 플레이어의 받는 피해를 15% 감소시킵니다.",actives={{unlock=1,desc="전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="주변 적들의 방어력을 5% 감소시킵니다."}}},[103]={enter="플레이어에게 2초간 기본 공격 피해 면역을 부여합니다.",actives={{unlock=1,desc="전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신의 공격 속도가 10%, 이동 속도가 10% 증가합니다."}}},[104]={enter="주변 적 6명에게 10% 피해를 5회 입히고, 1.5초간 빙결시킵니다.",actives={{unlock=1,desc="적에게 에너지 응집체를 날려 폭발시켜 주변 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 이동 속도를 15% 증가시킵니다."}}},[105]={enter="주변 적 6명에게 10% 피해를 5회 입히고, 10초간 받는 피해를 10% 증가시킵니다.",actives={{unlock=1,desc="적에게 에너지 응집체를 날려 폭발시켜 주변 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 공격력과 방어력을 8% 증가시킵니다."}}},[106]={enter="15초간 플레이어에게 지속 회복을 부여하여 1초마다 HP를 1% 회복시킵니다.",actives={{unlock=1,desc="적에게 에너지 응집체를 날려 폭발시켜 주변 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 최대 데미지 배율을 12% 증가시킵니다."}}},[107]={enter="10초간 플레이어의 공격 속도를 15% 증가시킵니다.",actives={{unlock=1,desc="다수의 화살을 발사하여 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 크리티컬 확률을 8% 증가시킵니다."}}},[108]={enter="플레이어의 디버프를 1개 제거하고 3초간 디버프 면역을 부여합니다.",actives={{unlock=1,desc="다수의 화살을 발사하여 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 크리티컬 확률을 8% 증가시킵니다."}}},[109]={enter="주변 적 8명에게 30% 피해를 4회 입힙니다. 대상이 보스라면 피해량이 3배로 적용됩니다.",actives={{unlock=1,desc="표창을 던져 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 명중을 6 증가시킵니다."}}},[110]={enter="대상의 버프를 1개 제거하고 80% 피해를 2회 입힙니다.",actives={{unlock=1,desc="주변 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 크리티컬 데미지를 8% 증가시킵니다."}}},[111]={enter="10초간 동료 자신과 플레이어의 공격 속도를 8%, 크리티컬 데미지를 8% 증가시킵니다.",actives={{unlock=1,desc="점프 후 뒤로 회전하며 다리로 주변 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 크리티컬 확률을 10% 증가시킵니다."}}},[112]={enter="주변 적 6명에게 17% 피해를 3회 입히고 1.5초간 기절시킵니다.",actives={{unlock=1,desc="탄환을 연속 발사하여 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 공격 속도를 10% 증가시킵니다."}}},[113]={enter="10초간 플레이어의 크리티컬 저항을 15% 증가시키고, 최대 HP의 10%만큼 피해를 흡수하는 보호막을 부여합니다.",actives={{unlock=1,desc="전방에 표창을 던져 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnAttack",chance=30,desc="공격 시 30% 확률로 대상에게 20% 추가 피해를 입히고, 3초간 공격력을 15% 감소시킵니다."}}},[114]={enter="주변 임의의 적에게 13% 추가 피해를 입히는 [정령의 기운]을 15개 생성합니다. [정령의 기운]은 50% 확률로 강화되어 2배의 피해를 입힙니다.",actives={{unlock=1,desc="바람의 힘을 실은 화살을 날려 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 공격력을 8% 증가시킵니다."}}},[115]={enter="30초간 동료 주변의 적 12명 중 보스가 아닌 적의 받는 피해를 4% 증가시킵니다. [챕터 도전] 전투 시 3배로 적용됩니다.",actives={{unlock=1,desc="화염을 날려 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 공격력을 4%, 동료 자신의 공격력을 12% 증가시킵니다."}}},[116]={enter="동료 자신과 플레이어의 공격력을 8% 증가시킵니다. 플레이어에게는 10초간, 동료 자신에게는 소환 지속시간 동안 적용됩니다.",actives={{unlock=1,desc="태양을 베어 내듯 검을 휘둘러 전방의 적 3명에게 26% 피해를 2회 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 스킬 데미지를 10% 증가시킵니다."}}},[201]={enter="10초간 플레이어의 방어력을 15% 증가시키고, 최대 HP의 20%만큼 피해를 흡수하는 보호막을 부여합니다.",actives={{unlock=1,desc="전방의 적 5명에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=22,desc="전방의 적 7명에게 250% 피해를 입히고, 1.5초간 기절시킵니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="주변 적들의 공격력을 15% 감소시킵니다."},{unlock=3,trigger="OnAttack",chance=40,desc="공격 시 40% 확률로 10초간 동료 자신과 플레이어의 공격력이 5% 증가하는 콤보를 획득합니다. 콤보는 최대 5회 중첩됩니다."}}},[202]={enter="15초간 플레이어의 받는 피해를 15% 감소시킵니다.",actives={{unlock=1,desc="전방의 적 5명에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=18,desc="주변 적 7명에게 260% 피해를 입히고, 10초간 방어력을 10% 감소시킵니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="주변 적들의 방어력을 5% 감소시킵니다."},{unlock=3,trigger="OnAttack",chance=15,desc="기본 공격 시 15% 확률로 10초간 동료 자신과 플레이어의 크리티컬 데미지가 15% 증가합니다."}}},[203]={enter="플레이어에게 2.5초간 기본 공격 피해 면역을 부여합니다.",actives={{unlock=1,desc="창을 휘둘러 전방의 적 5명에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=25,desc="플레이어의 HP를 20% 회복시키고, 10초간 최대 HP를 20% 증가시킵니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신의 공격 속도가 15%, 이동 속도가 15% 증가합니다."},{unlock=3,trigger="OnStart",chance=100,desc="비홀더를 소환합니다. 비홀더는 동료의 소환 지속시간 동안 유지되며 주변 적 6명의 받는 피해를 15% 증가시킵니다."}}},[204]={enter="주변 적 8명에게 30% 피해를 5회 입히고, 2초간 빙결시킵니다.",actives={{unlock=1,desc="전방에 얼음 수정을 소환하여 5명의 적에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=30,desc="15초간 동료 자신과 플레이어의 공격력을 20% 증가시킵니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="동료 자신과 플레이어의 이동 속도를 20% 증가시킵니다."},{unlock=3,trigger="OnStart",chance=100,desc="주변 적들의 크리티컬 저항을 10% 감소시킵니다."}}},[205]={enter="주변 적 8명에게 30% 피해를 5회 입히고, 10초간 받는 피해를 15% 증가시킵니다.",actives={{unlock=1,desc="전방에 불타는 오브를 발사하여 5명에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=12,desc="대기를 맹독성으로 바꿔 주변 적 6명에게 50% 피해를 3회 입히고, 10초간 중독 상태로 만들어 0.5초마다 10% 지속 피해를 입힙니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 공격력과 방어력을 12% 증가시킵니다."},{unlock=3,trigger="OnTimer",chance=100,desc="3초마다 주변 적 위치에 불의 벽을 생성하여 그 위의 적 3명에게 1초마다 12% 지속 피해를 입힙니다."}}},[206]={enter="20초간 플레이어에게 지속 회복을 부여하여 1초마다 HP를 1% 회복시킵니다.",actives={{unlock=1,desc="성스러운 화살을 발사하여 전방의 적 5명에게 40% 피해를 3회 입힙니다."},{unlock=1,cd=15,desc="10초간 플레이어에게 지속 회복을 부여하여 1초마다 HP를 1% 회복시킵니다. 스킬 지속시간 동안 현재 HP가 30% 이상이라면, 공격력이 15% 증가합니다."}},passives={{unlock=1,trigger="OnStart",chance=100,desc="플레이어의 최대 데미지 배율을 18% 증가시킵니다."},{unlock=3,trigger="OnTimer",chance=100,desc="2초마다 플레이어의 MP를 3% 회복시킵니다. MP 회복 직후 플레이어의 MP가 50% 이상이라면, 5초간 최종 데미지가 8% 증가합니다."}}},[207]={enter="15초간 플레이어의 공격 속도를 15% 증가시킵니다.",actives={{unlock=